{"command": "cd /tmp/zo && python3 - <<'EOF'
import sys; sys.path.insert(0,'/tmp/zo')
from wdb import write
import os, time, subprocess, shutil, struct
env=os.environ|{'_ZO_DATA_DIR':'/tmp/zo/data'}
now=int(time.time())
def add(*paths):
    return subprocess.run(['/workspace/executable','add']+list(paths),env=env,capture_output=True,text=True)
def show():
    d=open('/tmp/zo/data/db.zo','rb').read()
    n=struct.unpack_from('<Q',d,4)[0]; o=12; out=[]
    for i in range(n):
        l=struct.unpack_from('<Q',d,o)[0]; o+=8
        p=d[o:o+l].decode(); o+=l
        r=struct.unpack_from('<d',d,o)[0]; o+=8
        t=struct.unpack_from('<Q',d,o)[0]; o+=8
        out.append((p,r,t))
    return out
os.makedirs('/tmp/zx/ab',exist_ok=True); os.makedirs('/tmp/zx/cd',exist_ok=True)
for ranks in [[(10000.0,'ab')],[(9999.0,'ab')],[(9998.0,'ab')],[(5000.0,'ab'),(5000.0,'cd')],[(5000.0,'ab'),(5001.0,'cd')],[(3000.0,'ab'),(3000.0,'cd'),(3000.0,'ef')]]:
    ents=[]
    for (r,nm) in ranks:
        os.makedirs('/tmp/zx/'+nm,exist_ok=True)
        ents.append((f'/tmp/zx/{nm}',r,now))
    shutil.rmtree('/tmp/zo/data',ignore_errors=True)
    write(ents)
    add(f'/tmp/zx/{ranks[0][1]}')
    print(f"in={ranks} -> {show()}")
EOF"}

