import sys; sys.path.insert(0,'/tmp/zo')
from wdb import write
import os, time, subprocess, shutil, struct
env=os.environ|{'_ZO_DATA_DIR':'/tmp/zo/data'}
now=int(time.time())
def add(*paths, **kw):
    return subprocess.run(['/workspace/executable','add']+list(paths),env=env,capture_output=True,text=True)
def show():
    d=open('/tmp/zo/data/db.zo','rb').read()
    n=struct.unpack_from('<Q',d,4)[0]; o=12; out=[]
    for i in range(n):
        l=struct.unpack_from('<Q',d,o)[0]; o+=8
        p=d[o:o+l].decode(); o+=l
        r=struct.unpack_from('<d',d,o)[0]; o+=8
        t=struct.unpack_from('<Q',d,o)[0]; o+=8
        out.append((p,round(r,6),t))
    return out
for nm in ['ab','cd']: os.makedirs('/tmp/zx/'+nm,exist_ok=True)
tests=[
 ("2x10000 now, add ab", [('/tmp/zx/ab',10000,now),('/tmp/zx/cd',10000,now)], ['ab'], ()),
 ("2x6000 year-old, add ab", [('/tmp/zx/ab',6000,now-31536000),('/tmp/zx/cd',6000,now-31536000)], ['ab'], ()),
 ("9999 now + add -s 5", [('/tmp/zx/ab',9999,now)], ['ab'], ('-s','5')),
 ("0.5+0.5 ranks", [('/tmp/zx/ab',0.5,now),('/tmp/zx/cd',0.5,now)], ['ab'], ()),
 ("10000+0.5 ranks", [('/tmp/zx/ab',10000,now),('/tmp/zx/cd',0.5,now)], ['ab'], ()),
 ("10000+1.5 ranks", [('/tmp/zx/ab',10000,now),('/tmp/zx/cd',1.5,now)], ['ab'], ()),
]
for name, ents, adds, extra in tests:
    shutil.rmtree('/tmp/zo/data',ignore_errors=True)
    write([(p,r,t) for (p,r,t) in ents])
    add(*[a for a in adds], *extra)
    print(f"{name} -> {show()}")
EOF"}

