/// The shells supported by `zoxide init`.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Shell {
    Bash,
    Zsh,
    Fish,
    Posix,
    Powershell,
    Elvish,
    Nushell,
    Xonsh,
    Tcsh,
}

/// How often zoxide increments a directory's score.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Hook {
    None,
    Prompt,
    Pwd,
}

fn sub_cmd(s: &str, cmd: &str) -> String {
    s.replace('\u{1}', cmd).replace('\u{2}', &format!("{cmd}i"))
}

/// Generate the shell configuration script.
pub fn init(shell: Shell, cmd: &str, hook: Hook, no_cmd: bool, echo: bool, resolve: bool) -> String {
