            }
            if resolve {
                s = s.replace("    \\builtin pwd -L\n", "    \\builtin pwd -P\n");
            }
        }
        Shell::Zsh => {
            s.push_str(Zsh_PREFIX);
            s.push_str(hook_str(hook, Zsh_HOOK_NONE, Zsh_HOOK_PROMPT, Zsh_HOOK_PWD));
            s.push_str(Zsh_MIDDLE);
            s.push_str(if no_cmd {
