                s.push('\n');
                s.push_str(&Zsh_CMDS_COMPDEF.replace('\u{1}', cmd));
            }
            s.push_str(Zsh_CMDS_TAIL);
            s.push_str(Zsh_FOOTER);
            if echo {
                s = s.replace("    \\builtin cd -- \"$@\"\n", "    \\builtin cd -- \"$@\" && __zoxide_pwd\n");
            }
            if resolve {
                s = s.replace("    \\builtin pwd -L\n", "    \\builtin pwd -P\n");
            }
        }
        Shell::Fish => {
            s.push_str(Fish_PREFIX);
            s.push_str(hook_str(hook, Fish_HOOK_NONE, Fish_HOOK_PROMPT, Fish_HOOK_PWD));
            s.push_str(Fish_MIDDLE);
            s.push_str(if no_cmd { Fish_CMDS_NONE } else { &sub_cmd(Fish_CMDS, cmd) });
            s.push_str(Fish_FOOTER);
            if echo {
                s = s.replace(
                    "    __zoxide_loop=1 __zoxide_cd_internal $argv\nend\n",
                    "    __zoxide_loop=1 __zoxide_cd_internal $argv\n    and __zoxide_pwd\nend\n",
                );
            }
            if resolve {
                s = s.replace("    builtin pwd -L\n", "    builtin pwd -P\n");
            }
        }
        Shell::Posix => {
            s.push_str(Posix_PREFIX);
            s.push_str(hook_str(hook, Posix_HOOK_NONE, Posix_HOOK_PROMPT, Posix_HOOK_PWD));
            s.push_str(Posix_MIDDLE);
            s.push_str(if no_cmd { Posix_CMDS_NONE } else { &sub_cmd(Posix_CMDS, cmd) });
            s.push_str(Posix_FOOTER);
            if echo {
                s = s.replace("    \\command cd \"$@\"\n", "    \\command cd \"$@\" && __zoxide_pwd\n");
            }
            if resolve {
                s = s.replace("    \\command pwd -L\n", "    \\command pwd -P\n");
            }
        }
        Shell::Powershell => {
            s.push_str(Powershell_PREFIX);
            s.push_str(hook_str(hook, Powershell_HOOK_NONE, Powershell_HOOK_PROMPT, Powershell_HOOK_PWD));
            s.push_str(Powershell_MIDDLE);
            s.push_str(if no_cmd { Powershell_CMDS_NONE } else { &sub_cmd(Powershell_CMDS, cmd) });
            s.push_str(Powershell_FOOTER);
            if echo {
                s = insert_before_last_brace(&s, "    Write-Output $dir.Path\n");
            }
        }
        Shell::Elvish => {
            s.push_str(Elvish_PREFIX);
            s.push_str(hook_str(hook, Elvish_HOOK_NONE, Elvish_HOOK_PROMPT, Elvish_HOOK_PWD));
            s.push_str(Elvish_MIDDLE);
            s.push_str(if no_cmd { Elvish_CMDS_NONE } else { &sub_cmd(Elvish_CMDS, cmd) });
            s.push_str(Elvish_FOOTER);
            if echo {
                s = s.replace("    builtin:cd $path\n}\n", "    builtin:cd $path\n    builtin:echo $pwd\n}\n");
            }
        }
        Shell::Nushell => {
            s.push_str(Nushell_PREFIX);
            s.push_str(hook_str(hook, Nushell_HOOK_NONE, Nushell_HOOK_PROMPT, Nushell_HOOK_PWD));
            s.push_str(Nushell_MIDDLE);
            s.push_str(if no_cmd { Nushell_CMDS_NONE } else { &sub_cmd(Nushell_CMDS, cmd) });
            s.push_str(Nushell_FOOTER);
            if echo {
                for a in NU_ANCHORS {
                    s = s.replace(a, &format!("{a}  echo $env.PWD\n"));
                }
            }
        }
        Shell::Xonsh => {
            s.push_str(Xonsh_PREFIX);
            s.push_str(hook_str(hook, Xonsh_HOOK_NONE, Xonsh_HOOK_PROMPT, Xonsh_HOOK_PWD));
            s.push_str(Xonsh_MIDDLE);
            s.push_str(if no_cmd { Xonsh_CMDS_NONE } else { &sub_cmd(Xonsh_CMDS, cmd) });
            s.push_str(Xonsh_FOOTER);
            if echo {
                s = s.replace(
                    "        raise RuntimeError(exc)\n",
                    "        raise RuntimeError(exc)\n    print(__zoxide_pwd())\n",
                );
            }
            if resolve {
                s = s.replace(
                    "    pwd = __zoxide_env().get(\"PWD\")\n    if pwd is None:\n        raise RuntimeError(\"$PWD not found\")\n",
                    "    pwd = os.getcwd()\n",
                );
            }
        }
        Shell::Tcsh => {
            s.push_str(Tcsh_PREFIX);
            s.push_str(hook_str(hook, Tcsh_HOOK_NONE, Tcsh_HOOK_PROMPT, Tcsh_HOOK_PWD));
            s.push_str(Tcsh_MIDDLE);
            s.push_str(if no_cmd { Tcsh_CMDS_NONE } else { &sub_cmd(Tcsh_CMDS, cmd) });
            s.push_str(Tcsh_FOOTER);
            if resolve {
                s = s.replace("pwd -L\n", "pwd -P\n");
            }
        }
    }
    s
}

fn hook_str(hook: Hook, none: &str, prompt: &str, pwd: &str) -> &'static str {
    match hook {
        Hook::None => none,
        Hook::Prompt => prompt,
        Hook::Pwd => pwd,
    }
}

const NU_ANCHORS: [&str; 2] = [
    "  cd $path\n",
    "  cd $'(^zoxide query --interactive -- ...$rest | str trim -r -c \"\\n\")'\n",
];

fn insert_before_last_brace(s: &str, insert: &str) -> String {
    // Insert before the last top-level closing brace of __zoxide_cd.
    let idx = s.rfind("    }\n}\n\n").expect("anchor");
    let mut out = String::with_capacity(s.len() + insert.len());
    out.push_str(&s[..idx + "    }\n".len()]);
    out.push_str(insert);
    out.push_str(&s[idx + "    }\n".len()..]);
    out
}
'''
src = consts + logic
