pub fn init(shell: Shell, cmd: &str, hook: Hook, no_cmd: bool, echo: bool, resolve: bool) -> String {
    let mut s = String::new();
    match shell {
        Shell::Bash => {
            s.push_str(Bash_PREFIX);
            s.push_str(match hook { Hook::None => Bash_HOOK_NONE, Hook::Prompt => Bash_HOOK_PROMPT, Hook::Pwd => Bash_HOOK_PWD });
            s.push_str(Bash_MIDDLE);
            s.push_str(&cmds_bash(cmd, no_cmd));
            s.push_str(Bash_FOOTER);
            if echo { s = s.replace("    \\builtin cd -- \"$@\"\n", "    \\builtin cd -- \"$@\" && __zoxide_pwd\n"); }
            if resolve { s = s.replace("    \\builtin pwd -L\n", "    \\builtin pwd -P\n"); }
        }
        ...
    }
    s
}
