use anyhow::{anyhow, Context, Result};
use std::path::{Component, Path, PathBuf};

/// Resolve the data directory.
///
/// Honours `_ZO_DATA_DIR`, falling back to the platform specific data dir.
pub fn data_dir() -> Result<Option<PathBuf>> {
    if let Some(dir) = std::env::var_os("_ZO_DATA_DIR") {
        let dir = PathBuf::from(dir);
        if !dir.is_absolute() {
            return Err(anyhow!("_ZO_DATA_DIR must be an absolute path"));
        }
        Ok(Some(dir))
    } else {
        Ok(dirs::data_dir())
    }
}

/// Absolute, lexically normalized path.
pub fn absolute_path(path: &Path) -> Result<PathBuf> {
    let path = if path.is_absolute() {
        path.to_path_buf()
    } else {
        let cwd = std::env::current_dir().context("could not get current directory")?;
        cwd.join(path)
    };
    Ok(normalize(&path))
}

fn normalize(path: &Path) -> PathBuf {
    let mut parts: Vec<Component> = Vec::new();
    let mut root = false;
    for c in path.components() {
        match c {
            Component::Prefix(_) | Component::RootDir => {
                root = true;
                parts.clear();
            }
            Component::CurDir => {}
            Component::ParentDir => {
                let popped = match parts.last() {
                    Some(Component::Normal(_)) => {
                        parts.pop();
                        true
                    }
                    _ => false,
                };
                if !popped && !root {
                    parts.push(c);
                }
            }
            Component::Normal(_) => parts.push(c),
        }
    }
    let mut out = PathBuf::new();
    if root {
        out.push(Component::RootDir.as_os_str());
    }
    for p in parts {
        out.push(p.as_os_str());
    }
    out
}

/// Glob patterns from `_ZO_EXCLUDE_DIRS`, split on the platform separator.
pub fn excluded_globs() -> Result<Vec<glob::Pattern>> {
    let Some(v) = std::env::var_os("_ZO_EXCLUDE_DIRS") else {
        return Ok(Vec::new());
    };
    let Some(v) = v.to_str() else {
        return Ok(Vec::new());
    };
    let mut pats = Vec::new();
    for g in v.split(std::path::MAIN_SEPARATOR_STR) {
        match glob::Pattern::new(g) {
            Ok(p) => pats.push(p),
            Err(e) => return Err(anyhow!("invalid glob in _ZO_EXCLUDE_DIRS: {g}").context(e)),
        }
    }
    Ok(pats)
}

pub fn is_excluded(globs: &[glob::Pattern], path: &Path) -> bool {
    globs.iter().any(|g| g.matches_path(path))
}

/// `_ZO_MAXAGE`, defaulting to 10000.
pub fn maxage() -> Result<u32> {
    match std::env::var("_ZO_MAXAGE") {
        Ok(v) => v
            .parse::<u32>()
            .with_context(|| format!("unable to parse _ZO_MAXAGE as integer: {v}")),
        Err(_) => Ok(10000),
    }
}

pub fn echo() -> bool {
    std::env::var("_ZO_ECHO").is_ok_and(|v| v == "1")
}

pub fn resolve_symlinks() -> bool {
    std::env::var("_ZO_RESOLVE_SYMLINKS").is_ok_and(|v| v == "1")
}

/// Current unix timestamp in seconds.
pub fn timestamp() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

pub fn env_flag(name: &str) -> bool {
    std::env::var(name).is_ok_and(|v| v == "1")
}
