use anyhow::{anyhow, Context, Result};
use std::io::Write;
use std::path::{Path, PathBuf};

pub const DB_VERSION: u32 = 3;
pub const DEFAULT_MAXAGE: u32 = 10000;

#[derive(Clone, Debug, PartialEq)]
pub struct DbEntry {
    pub path: PathBuf,
    pub rank: f64,
    pub timestamp: u64,
}

#[derive(Clone, Debug, Default)]
pub struct Database {
    pub entries: Vec<DbEntry>,
}

impl Database {
    pub fn load() -> Result<Database> {
        let Some(dir) = crate::util::data_dir()? else {
            return Ok(Database::default());
        };
        let path = dir.join("db.zo");
        let bytes = match std::fs::read(&path) {
            Ok(b) => b,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Database::default()),
            Err(e) => {
                return Err(anyhow::Error::new(e).context(format!(
                    "could not read from database: {}",
                    path.display()
                )))
            }
        };
        deserialize(&bytes)
    }

    pub fn store(&self) -> Result<()> {
        let Some(dir) = crate::util::data_dir()? else {
            return Ok(());
        };
        std::fs::create_dir_all(&dir)
            .with_context(|| format!("unable to create data directory: {}", dir.display()))?;
        let bytes = serialize(self);
        let name = format!("tmp_{}", rand_string(12));
        let tmp = dir.join(name);
        let mut f = std::fs::File::create(&tmp)
            .with_context(|| format!("could not create file: {}", tmp.display()))
            .context("could not write to database")?;
        f.write_all(&bytes)
            .with_context(|| format!("could not create file: {}", tmp.display()))
            .context("could not write to database")?;
        std::fs::rename(&tmp, dir.join("db.zo")).context("could not write to database")?;
        Ok(())
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Find the index of `path` in the database.
    pub fn find(&self, path: &Path) -> Option<usize> {
        self.entries.iter().position(|e| e.path == path)
    }

    /// Add (or increment) an entry. Returns true if the database changed.
    pub fn add(&mut self, path: &Path, rank: f64, now: u64) -> bool {
        match self.find(path) {
            Some(idx) => {
                let e = &mut self.entries[idx];
                e.rank = e.rank.plus(rank);
                e.timestamp = now;
            }
            None => self.entries.push(DbEntry {
                path: path.to_path_buf(),
                rank: rank.max(0.0),
                timestamp: now,
            }),
        }
        true
    }

    /// Increment (positive) or decrement (negative) the rank without touching the timestamp.
    pub fn modify(&mut self, path: &Path, delta: f64, now: u64) -> bool {
        match self.find(path) {
            Some(idx) => {
                let e = &mut self.entries[idx];
                e.rank = e.rank.plus(delta);
            }
            None => self.entries.push(DbEntry {
                path: path.to_path_buf(),
                rank: if delta < 0.0 { 0.0 } else { delta },
                timestamp: now,
            }),
        }
        true
    }

    pub fn remove(&mut self, path: &Path) -> bool {
        match self.find(path) {
            Some(idx) => {
                self.entries.remove(idx);
                true
            }
            None => false,
        }
    }

    /// Age the database so that the total rank stays below `maxage`.
    pub fn age(&mut self, maxage: u32) {
        let total: f64 = self.entries.iter().map(|e| e.rank).sum();
        if total > maxage as f64 {
            let factor = 0.9 * maxage as f64 / total;
            for e in &mut self.entries {
                e.rank *= factor;
            }
            self.entries.retain(|e| !(e.rank < 1.0));
        }
    }
}

trait Plus {
    fn plus(self, other: f64) -> f64;
}
impl Plus for f64 {
    fn plus(self, other: f64) -> f64 {
        (self + other).max(0.0)
    }
}

fn rand_string(len: usize) -> String {
    // Simple xorshift based generator seeded from the system clock and address entropy.
    use std::time::{SystemTime, UNIX_EPOCH};
    let mut seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0)
        ^ (std::process::id() as u64) << 1
        ^ (&seed_addr as *const _ as u64);
    const CHARS: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    let mut out = String::with_capacity(len);
    for _ in 0..len {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        out.push(CHARS[(seed % CHARS.len() as u64) as usize] as char);
    }
    out
}

static seed_addr: u8 = 0;

fn serialize(db: &Database) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(&DB_VERSION.to_le_bytes());
    out.extend_from_slice(&(db.entries.len() as u64).to_le_bytes());
    for e in &db.entries {
        let b = e.path.as_os_str().as_encoded_bytes();
        out.extend_from_slice(&(b.len() as u64).to_le_bytes());
        out.extend_from_slice(b);
        out.extend_from_slice(&e.rank.to_le_bytes());
        out.extend_from_slice(&e.timestamp.to_le_bytes());
    }
    out
}

fn deserialize(bytes: &[u8]) -> Result<Database> {
    if bytes.len() < 4 {
        return Err(anyhow!("could not deserialize database: corrupted data"));
    }
    let mut entries = Vec::new();
    let mut pos = 0usize;
    let mut read = |n: usize| -> Result<&[u8]> {
        if pos + n > bytes.len() {
            return Err(anyhow!("io error: unexpected end of file")
                .context("could not deserialize database"));
        }
        let s = &bytes[pos..pos + n];
        pos += n;
        Ok(s)
    };
    let v = {
        let b = read(4)?;
        u32::from_le_bytes([b[0], b[1], b[2], b[3]])
    };
    if v != DB_VERSION {
        return Err(anyhow!("unsupported version (got {v}, supports {DB_VERSION})"));
    }
    let count = {
        let b = read(8)?;
        u64::from_le_bytes([b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]])
    };
    for _ in 0..count {
        let len = {
            let b = read(8)?;
            u64::from_le_bytes([b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]])
        } as usize;
        let pb = read(len)?;
        let s = std::str::from_utf8(pb)
            .map_err(|e| anyhow!("string is not valid utf8: {e}").context("could not deserialize database"))?;
        let rb = read(8)?;
        let rank = f64::from_le_bytes([
            rb[0], rb[1], rb[2], rb[3], rb[4], rb[5], rb[6], rb[7],
        ]);
        let tb = read(8)?;
        let ts = u64::from_le_bytes([
            tb[0], tb[1], tb[2], tb[3], tb[4], tb[5], tb[6], tb[7],
        ]);
        entries.push(DbEntry {
            path: PathBuf::from(s),
            rank,
            timestamp: ts,
        });
    }
    if pos != bytes.len() {
        return Err(anyhow!("Slice had bytes remaining after deserialization")
            .context("could not deserialize database"));
    }
    Ok(Database { entries })
}
