        self.entries.is_empty()
    }

    /// Find the index of `path` in the database.
    pub fn find(&self, path: &Path) -> Option<usize> {
        self.entries.iter().position(|e| e.path == path)
    }

    /// Add (or increment) an entry. Returns true if the database changed.
    pub fn add(&mut self, path: &Path, rank: f64, now: u64) -> bool {
        match self.find(path) {
            Some(idx) => {
                let e = &mut self.entries[idx];
                e.rank = e.rank.plus(rank);
                e.timestamp = now;
            }
            None => self.entries.push(DbEntry {
                path: path.to_path_buf(),
                rank: rank.max(0.0),
                timestamp: now,
            }),
        }
        true
    }

    /// Increment (positive) or decrement (negative) the rank without touching the timestamp.
    pub fn modify(&mut self, path: &Path, delta: f64, now: u64) -> bool {
        match self.find(path) {
            Some(idx) => {
                let e = &mut self.entries[idx];
                e.rank = e.rank.plus(delta);
            }
            None => self.entries.push(DbEntry {
