        match self.find(path) {
            Some(idx) => {
                self.entries.remove(idx);
                true
            }
            None => false,
        }
    }

    /// Age the database so that the total rank stays below `maxage`.
    pub fn age(&mut self, maxage: u32) {
        let total: f64 = self.entries.iter().map(|e| e.rank).sum();
        if total > maxage as f64 {
            let factor = 0.9 * maxage as f64 / total;
            for e in &mut self.entries {
                e.rank *= factor;
            }
