use anyhow::{anyhow, Context, Result};
use std::io::Write;
use std::path::PathBuf;
use std::process::Stdio;

pub const PREVIEW: &str =
    "\\command -p ls -Cp --color=always --group-directories-first {2..}";
pub const PREVIEW_WINDOW: &str = "down,30%,sharp";

const COMMON_ARGS: [&str; 3] = ["--delimiter=\t", "--nth=2", "--read0"];

/// Result of running fzf.
pub enum Fzf {
    /// fzf exited successfully; the raw stdout is available.
    Output(String),
    /// fzf was interrupted (exit code 130); the process should exit with the same code.
    Interrupted,
}

/// Options describing how to launch fzf.
pub struct FzfOpts {
    pub extra_args: Vec<&'static str>,
    /// Pass `_ZO_FZF_OPTS` through `FZF_DEFAULT_OPTS` instead of the extra args.
    pub use_env_opts: bool,
}

pub fn query_opts() -> FzfOpts {
    FzfOpts {
        extra_args: vec![
            "--exact",
            "--no-sort",
            "--bind=ctrl-z:ignore,btab:up,tab:down",
            "--cycle",
            "--keep-right",
            "--border=sharp",
            "--height=45%",
            "--info=inline",
            "--layout=reverse",
            "--tabstop=1",
            "--exit-0",
            &concat_preview(),
            "--preview-window=down,30%,sharp",
        ],
        use_env_opts: true,
    }
}

fn concat_preview() -> String {
    format!("--preview={PREVIEW}")
}

pub fn edit_opts() -> FzfOpts {
    FzfOpts {
        extra_args: vec![
            "--exact",
            "--no-sort",
            "--bind=btab:up,ctrl-r:reload(zoxide edit reload),ctrl-d:reload(zoxide edit delete {2..}),ctrl-w:reload(zoxide edit increment {2..}),ctrl-s:reload(zoxide edit decrement {2..}),ctrl-z:ignore,double-click:ignore,enter:abort,start:reload(zoxide edit reload),tab:down",
            "--cycle",
            "--keep-right",
            "--border=sharp",
            "--border-label=  zoxide-edit  ",
            "--header=ctrl-r:reload   \tctrl-d:delete\nctrl-w:increment\tctrl-s:decrement\n\n SCORE\tPATH",
            "--info=inline",
            "--layout=reverse",
            "--padding=1,0,0,0",
            "--color=label:bold",
            "--tabstop=1",
            &concat_preview(),
            "--preview-window=down,30%,sharp",
        ],
        use_env_opts: false,
    }
}

/// Launch fzf, feed it `input` and return its result.
pub fn run(opts: &FzfOpts, input: &[u8]) -> Result<Fzf> {
    let mut cmd = std::process::Command::new("fzf");
    for a in COMMON_ARGS {
        cmd.arg(a);
    }
    if opts.use_env_opts {
        if let Some(o) = std::env::var_os("_ZO_FZF_OPTS") {
            cmd.env("FZF_DEFAULT_OPTS", o);
        } else {
            for a in &opts.extra_args {
                cmd.arg(a);
            }
        }
    } else {
        for a in &opts.extra_args {
            cmd.arg(a);
        }
    }
    cmd.stdin(Stdio::piped()).stdout(Stdio::piped());
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            return Err(anyhow!("could not find fzf, is it installed?"))
        }
        Err(e) => return Err(anyhow::Error::new(e).context("could not launch fzf")),
    };
    if !input.is_empty() {
        let mut stdin = child.stdin.take().expect("stdin");
        let data = input.to_vec();
        std::thread::spawn(move || {
            let _ = stdin.write_all(&data);
        });
    }
    let output = child.wait_with_output().context("could not launch fzf")?;
    match output.status.code() {
        Some(0) => {}
        Some(1) => return Err(anyhow!("no match found")),
        Some(2) => return Err(anyhow!("fzf returned an error")),
        Some(130) => return Ok(Fzf::Interrupted),
        Some(129) => return Err(anyhow!("fzf was terminated")),
        Some(_) => return Err(anyhow!("fzf returned an unknown error")),
        None => return Err(anyhow!("fzf was terminated")),
    }
    let stdout = String::from_utf8(output.stdout)
        .map_err(|e| anyhow::Error::new(e).context("failed to read from fzf"))?;
    Ok(Fzf::Output(stdout))
}

/// Extract the path from an fzf selection.
///
/// The score column is a fixed width of 6 characters followed by a tab.
pub fn selection_to_path(sel: &str) -> Result<String> {
    sel.get(7..).map(|s| s.to_string()).ok_or_else(|| anyhow!("could not read selection from fzf"))
}

pub fn score_str(score: f64) -> String {
    format!("{:>6.1}", score.clamp(0.0, 9999.0))
}

pub fn fmt_entry(score: f64, path: &std::path::Path) -> String {
    format!("{}\t{}\0", score_str(score), path.display())
}

pub fn _unused(_: PathBuf) {}
