use crate::db::Database;
use crate::util::{absolute_path, excluded_globs, is_excluded, maxage, timestamp};
use anyhow::{anyhow, Context, Result};
use clap::ArgMatches;
use std::path::PathBuf;

pub fn run(m: &ArgMatches) -> Result<()> {
    let score = m.get_one::<f64>("score").copied().unwrap_or(1.0);
    let globs = excluded_globs()?;
    let mut db = Database::load()?;
    let maxage = maxage()?;
    let now = timestamp();

    let mut paths: Vec<PathBuf> = Vec::new();
    for p in m.get_many::<String>("paths").expect("paths") {
        let p = absolute_path(&std::path::PathBuf::from(p))?;
        let p = p
            .to_str()
            .ok_or_else(|| anyhow!("invalid unicode in path: {}", p.display()))?;
        let p = std::path::PathBuf::from(p);
        if is_excluded(&globs, &p) {
            continue;
        }
        if !p.is_dir() {
            return Err(anyhow!("not a directory: {}", p.display()));
        }
        paths.push(p);
    }
    if paths.is_empty() {
        return Ok(());
    }
    for p in &paths {
        db.add(p, score, now);
    }
    db.age(maxage);
    db.store()?;
    Ok(())
}

pub fn _unused() -> Result<()> {
    Ok(())
}

pub fn ctx() -> Context {
    anyhow!("x").context("y")
}
