use crate::db::{Database, DbEntry};
use crate::interactive::{self, Fzf};
use crate::util::{excluded_globs, is_excluded};
use anyhow::{anyhow, Result};
use clap::ArgMatches;
use std::path::Path;

/// Match `keywords` against `path`.
///
/// Keywords are matched from the end of the path backwards; each keyword's
/// match must end at or before the start of the following keyword's match.
/// The last keyword's match has to reach into the final path component.
fn matches(path: &Path, keywords: &[String]) -> bool {
    let Some(s) = path.to_str() else { return false };
    let lowered = s.to_lowercase();
    let last_comp_start = lowered.rfind('/').map(|i| i + 1).unwrap_or(0);
    let mut limit = lowered.len();
    for (i, kw) in keywords.iter().enumerate().rev() {
        let kw = kw.to_lowercase();
        let (start, end) = match rfind(&lowered[..limit], &kw) {
            Some(m) => m,
            None => return false,
        };
        if i == keywords.len() - 1 && end < last_comp_start {
            return false;
        }
        limit = start;
    }
    true
}

/// Find the rightmost occurrence of `pat` in `s`, returning (start, end).
fn rfind(s: &str, pat: &str) -> Option<(usize, usize)> {
    if pat.is_empty() {
        return Some((s.len(), s.len()));
    }
    s.rmatch_indices(pat).next().map(|(i, m)| (i, i + m.len()))
}

trait RMatchIndices {
    fn rmatch_indices(&self, pat: &str) -> impl Iterator<Item = (usize, &str)>;
}
impl RMatchIndices for str {
    fn rmatch_indices(&self, pat: &str) -> impl Iterator<Item = (usize, &str)> {
        self.match_indices(pat).rev()
    }
}

pub fn score_of(e: &DbEntry) -> f64 {
    e.rank * frecency(e.timestamp)
}

/// Weighting factor depending on how long ago the entry was touched.
pub fn frecency(timestamp: u64) -> f64 {
    let now = crate::util::timestamp();
    let age = now.saturating_sub(timestamp);
    if age < 3600 {
        4.0
    } else if age < 86400 {
        2.0
    } else if age < 604800 {
        0.5
    } else {
        0.2
    }
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let all = m.get_flag("all");
    let interactive = m.get_flag("interactive");
    let list = m.get_flag("list");
    let score = m.get_flag("score");
    let exclude = m.get_one::<String>("exclude");
    let base_dir = m.get_one::<String>("base_dir");
    let keywords: Vec<String> = m
        .get_many::<String>("keywords")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let globs = excluded_globs()?;
    let db = Database::load()?;

    let base_dir = base_dir.map(Path::new);
    let mut matched: Vec<&DbEntry> = Vec::new();
    for e in db.entries.iter().rev() {
        if !keywords.is_empty() && !matches(&e.path, &keywords) {
            continue;
        }
        if let Some(b) = base_dir {
            if !e.path.starts_with(b) {
                continue;
            }
        }
        matched.push(e);
    }
    let candidates: Vec<&DbEntry> = matched
        .iter()
        .copied()
        .filter(|e| e.path.is_dir())
        .collect();

    // Remove excluded entries from the database.
    let pruned: Vec<PathBuf> = candidates
        .iter()
        .filter(|e| is_excluded(&globs, &e.path))
        .map(|e| e.path.clone())
        .collect();
    if !pruned.is_empty() {
        let mut db2 = db.clone();
        db2.entries.retain(|e| !pruned.contains(&e.path));
        db2.store()?;
    } else {
        db.store()?;
    }

    let results: Vec<&DbEntry> = if all { matched } else { candidates };
    let results: Vec<&DbEntry> = results
        .into_iter()
        .filter(|e| {
            if let Some(x) = exclude {
                e.path.as_os_str() != std::ffi::OsStr::new(x.as_str())
            } else {
                !is_excluded(&globs, &e.path)
            }
        })
        .collect();

    let mut results: Vec<(&DbEntry, f64)> = results
        .into_iter()
        .map(|e| (e, score_of(e)))
        .collect();
    results.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

    if interactive {
        let input: Vec<u8> = results
            .iter()
            .map(|(e, s)| interactive::fmt_entry(*s, &e.path))
            .collect::<Vec<_>>()
            .join(&[])
            .into_bytes();
        let out = interactive::run(&interactive::query_opts(), &input)?;
        match out {
            Fzf::Interrupted => std::process::exit(130),
            Fzf::Output(o) => {
                let p = interactive::selection_to_path(&o)?;
                print!("{p}");
            }
        }
        return Ok(());
    }

    if list {
        let mut out = String::new();
        for (e, s) in &results {
            if score {
                out.push_str(&interactive::score_str(*s));
                out.push(' ');
            }
            out.push_str(&e.path.display().to_string());
            out.push('\n');
        }
        print!("{out}");
        return Ok(());
    }

    match results.first() {
        Some((e, s)) => {
            if score {
                println!("{} {}", interactive::score_str(*s), e.path.display());
            } else {
                println!("{}", e.path.display());
            }
            Ok(())
        }
        None => Err(anyhow!("no match found")),
    }
}
